# -*- coding: utf-8 -*-
from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
B=[['拉丁 vicis；vic-','轮换、改变、替代'],['拉丁 vicarius','代替他人的；代理人']]
V=B+[['古法语 vicaire；盎格鲁法语 vicar 等 → 中古英语 vicar','代理人的名称用于教会职务'],['现代英语 vicar','尤指圣公会的教区牧师']]
A=B+[['英语 vicarious','以 -ous 形式借用拉丁词，起初指替代、代行'],['vicarious 的体验义','通过别人的经历，间接获得自己的感受']]
W=[E('vicar','英 /ˈvɪkə/；美 /ˈvɪkər/','教区牧师；教会代理人','小说里主持村中礼拜、照料教区的人，常被称为 the vicar。','拉丁 vicarius“代理人”经古法语、盎格鲁法语进入中古英语。深处是 vicis“轮换、替代”，现代职称却不能直接翻成普通“替班的人”。',V,'在英国语境中，vicar 通常指负责一个教区的圣公会牧师；其他教会中也可指代表上级履职的神职人员。不要把所有宗教的主持者都统一叫 vicar。','the village vicar；the local vicar；a parish vicar；speak to the vicar。','priest 是较宽的神职称呼，vicar 是具体职务名称。它与 vicarious 同接 vicarius，但后者不是由现代英语 vicar 加后缀才出现的。',('The vicar welcomed the new families to the parish.','教区牧师欢迎新搬来的几户人家。'),('After the service, we spoke to the vicar outside the church.','礼拜结束后，我们在教堂外和牧师聊了聊。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/vicar','https://www.etymonline.com/word/vicar']),
E('vicarious','英 /vɪˈkeəriəs/；美 /vaɪˈkeriəs/','间接体验到的；代替他人的','别人亲自经历，你通过观看、阅读或想象跟着体验。','来自拉丁 vicarius“替代的、代行的”，英语采用 -ous 形容词形式。先是“代替”，后来发展出“借别人的经历获得感受”。',A,'vicarious pleasure 可以是看别人旅行，自己也仿佛享受到风景。vicarious embarrassment 则是看到别人的窘境，自己也替他尴尬，不一定是高兴的体验。','vicarious pleasure；a vicarious thrill；vicarious experience；vicarious embarrassment。','indirect 泛指间接；vicarious 更具体地把另一个人的经历当成自己的体验通道。它不等于假装体验，感受本身可以很真实。',('Her travel diary gave me the vicarious pleasure of crossing the desert.','读她的旅行日记，让我间接体验了一次穿越沙漠的乐趣。'),('I felt vicarious embarrassment when the speaker forgot his own introduction.','演讲者忘了自己的开场白，我在台下也替他尴尬。'),sources=['https://www.etymonline.com/word/vicarious','https://www.oxfordlearnersdictionaries.com/definition/english/vicarious']),
E('vicariously','英 /vɪˈkeəriəsli/；美 /vaɪˈkeriəsli/','通过别人的经历间接地','自己没去做，却跟着别人的经历过了一把瘾。','vicarious + -ly，把间接体验的性质变成动作的方式。词根仍是“由别人代替”，不是“牧师式地”。',A+[['英语 vicarious + -ly → vicariously','通过他人间接地体验']],'live vicariously through someone 常指从别人的生活中寻找体验或满足。可以温和地说跟着朋友旅行，也可能批评父母把自己的梦想压在孩子身上，要看上下文。','live vicariously through someone；experience something vicariously；enjoy something vicariously。','virtually 是几乎、虚拟地等意思；vicariously 需要“通过他人的经历”这层关系，不必发生在网上。',('I travelled vicariously through my sister’s letters from abroad.','我读着姐姐从国外寄来的信，也间接体验了一场旅行。'),('He enjoyed the race vicariously through his daughter’s excited account.','听女儿兴奋地讲起比赛，他也跟着体会到了其中的乐趣。'),sources=['https://en.wiktionary.org/wiki/vicariously','https://www.oxfordlearnersdictionaries.com/definition/english/vicariously']),
E('vicarage','英美 /ˈvɪkərɪdʒ/','牧师住宅','住的是 vicar，这座房子便可以叫 vicarage。','中古英语在 vicar 上加 -age。早期可指牧师的职务、圣俸职位，随后也用于牧师的住处；现代最常见的是住宅义。',V[:-1]+[['中古英语 vicar + -age → vicarage','牧师的职务、圣俸职位；继而指牧师住宅'],['现代英语 vicarage','通常指教区牧师的住宅']],'the old vicarage 是旧牧师住宅；即使后来改作民居，建筑名称也可能保留。不要把它当成进行礼拜的教堂。','the old vicarage；the vicarage garden；live at the vicarage。','church 是教堂，vicarage 是牧师住处；-age 在这里不是英语 age“年龄”。',('The old vicarage has been converted into a family home.','旧牧师住宅已经改成了一户人家的住房。'),('The villagers held a summer sale in the vicarage garden.','村民们在牧师住宅的花园里办了一场夏季义卖。'),sources=['https://www.etymonline.com/word/vicarage','https://www.oxfordlearnersdictionaries.com/definition/english/vicarage']),
E('vicissitude','英 /vɪˈsɪsɪtjuːd/；美 /vɪˈsɪsɪtuːd/','变迁；兴衰起伏、人生波折','生活不会一直停在同一个位置：有顺境，也有转折和难关。','拉丁 vicis“轮换”→ 副词 vicissim“轮流地”→ 名词 vicissitudo“交替、变化”；经法语或直接从拉丁借入。不是 vicarious 的派生词。',[['拉丁 vicis → vicissim → vicissitudo','轮换 → 轮流地 → 交替、变化'],['法语 vicissitude 或直接拉丁借入 → 英语 vicissitude','变化、变迁'],['常用复数 vicissitudes','生活、命运或事业中的起落与波折']],'the vicissitudes of life 通常不是每天换一件衣服，而是生活中必须面对的重大变化、起落和困难。多用复数，带正式或文学色彩。','the vicissitudes of life；the vicissitudes of fortune；survive the vicissitudes of a career。','change 是普通的变化；vicissitudes 更容易让人想到反复的起伏，以及这些变化带来的考验。',('Their friendship survived the vicissitudes of forty years.','他们的友谊经受住了四十年间种种变迁的考验。'),('The memoir describes the vicissitudes of a life spent at sea.','这本回忆录描写了海上生涯的起伏与波折。'),sources=['https://www.etymonline.com/word/vicissitude','https://www.oxfordlearnersdictionaries.com/definition/english/vicissitude'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C1632');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C1632');keep={w['word']for w in W};excluded={w:'暂略低频条目。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C1632',meaning='轮换；替代',core='vic- 的核心是“换一个来”：位置轮换，人也可以相互代替。',image='你没站到那个位置，却通过另一个人的经历看见了那边的风景。',intro='vicar 从“代理人”发展为教会职称；vicarious、vicariously 把替代关系用在间接体验上；vicissitudes 则保留轮换变化的线索，指人生的起伏。',forms='拉丁 vicis 表轮换、改变；vicarius 是替代的、代理人，vicissim 是轮流地，再生出 vicissitudo。几个英语词分别沿不同路线借入。',branches=[['代理职务与住处','vicar、vicarage'],['通过他人体验','vicarious、vicariously'],['交替变化','vicissitude']],contrasts='职位中的 vice- 也有代替、副职的意思；vice“恶习”来自 vitium，不能混成一个词源。',practice='描述一次从电影或朋友故事中获得的 vicarious experience，再用 vicariously 改写。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/vicarious','https://www.etymonline.com/word/vicissitude'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_192_vic.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C1632',len(W),'new',len(ROOT[0]['words']),'retained')
